from .clients import Quasar
from .common import put,safe
def run(process,persona,country,conversation_id,**kwargs):
 mapped='HR' if 'hr' in persona.lower() else 'Manager' if 'leader' in persona.lower() else 'Employee' if 'as self' in persona.lower() else persona; q=Quasar(); p={'output':'IndexfileName: <IndexfileName>','query':f"@content: <Process>='{process}' <Persona>={mapped} @metadata:UserTrainingMaterialIndex.xlsx",'index':'wd_TSEndUserTrainingMaterials_idx','search_limit':'1'}; name=q.post('/api/v2/acnopenai/searchvectors',p).text.split(':')[-1].strip(' []\"'); p2={'query':f'@metadata:{name}','prompt_template':'*','primary_index':'wd_TSEndUserTrainingMaterials_idx','secondary_index':'wd_TSEndUserTrainingMaterials_idx','prompt_objective':'Return document text only','max_count':100,'chunk_size':2}; content=q.post('/api/v2/acnopenai/searchandgenerate',p2).text; out=f'{process}_{persona}_{country}_{safe(conversation_id)}_indexfile_content.txt'; put(out,content); return {'index_content':out}
